CREATE TABLE IF NOT EXISTS universal_observations(id TEXT PRIMARY KEY,jobId TEXT NOT NULL UNIQUE REFERENCES jobs(id),predictionId TEXT REFERENCES predictions(id),fixtureRevisionId TEXT NOT NULL REFERENCES fixture_revisions(id),bundleId TEXT NOT NULL REFERENCES input_bundles(id),state TEXT NOT NULL CHECK(state IN('DONE','BLOCKED')),outputJson TEXT NOT NULL,outputHash TEXT NOT NULL,calculatedAt INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS universal_fixture ON universal_observations(fixtureRevisionId,calculatedAt);
CREATE TABLE IF NOT EXISTS paper_policies(id TEXT PRIMARY KEY,portfolioId TEXT NOT NULL UNIQUE REFERENCES portfolios(id),label TEXT NOT NULL,strategyVersion TEXT NOT NULL UNIQUE,enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),maximumPerDay INTEGER NOT NULL CHECK(maximumPerDay BETWEEN 1 AND 100),revision INTEGER NOT NULL DEFAULT 0);
